import React from 'react';
import Hero from './Hero';
import Features from './Features';

export default function Home({ setCurrentPage }) {
  return (
    <div>
      <Hero setCurrentPage={setCurrentPage} />
      
      {/* Soft Modern Floating Stats Section */}
      <div style={{ 
        backgroundColor: '#f0fdf4', 
        padding: '45px 20px', 
        borderTop: '2px solid #bbf7d0',
        borderBottom: '2px solid #bbf7d0' 
      }}>
        <div style={{ 
          maxWidth: '1100px', 
          margin: '0 auto', 
          display: 'flex', 
          justify: 'center', 
          flexWrap: 'wrap', 
          gap: '25px', 
          textAlign: 'center' 
        }}>
          
          {/* Card 1 */}
          <div style={{ 
            flex: '1', 
            minWidth: '240px', 
            backgroundColor: '#ffffff', 
            padding: '25px 20px', 
            borderRadius: '16px', 
            boxShadow: '0 4px 15px rgba(62, 160, 6, 0.08)',
            border: '1px solid #dcfce7'
          }}>
            <h2 style={{ fontSize: '38px', margin: '0 0 5px 0', color: '#3ea006', fontWeight: '800' }}>9+</h2>
            <p style={{ margin: 0, fontSize: '15px', color: '#334155', fontWeight: '600' }}>Expert Subject Teachers</p>
          </div>

          {/* Card 2 */}
          <div style={{ 
            flex: '1', 
            minWidth: '240px', 
            backgroundColor: '#ffffff', 
            padding: '25px 20px', 
            borderRadius: '16px', 
            boxShadow: '0 4px 15px rgba(62, 160, 6, 0.08)',
            border: '1px solid #dcfce7'
          }}>
            <h2 style={{ fontSize: '38px', margin: '0 0 5px 0', color: '#3ea006', fontWeight: '800' }}>Modern</h2>
            <p style={{ margin: 0, fontSize: '15px', color: '#334155', fontWeight: '600' }}>Physical & Digital Classrooms</p>
          </div>

          {/* Card 3 */}
          <div style={{ 
            flex: '1', 
            minWidth: '240px', 
            backgroundColor: '#ffffff', 
            padding: '25px 20px', 
            borderRadius: '16px', 
            boxShadow: '0 4px 15px rgba(62, 160, 6, 0.08)',
            border: '1px solid #dcfce7'
          }}>
            <h2 style={{ fontSize: '38px', margin: '0 0 5px 0', color: '#3ea006', fontWeight: '800' }}>100%</h2>
            <p style={{ margin: 0, fontSize: '15px', color: '#334155', fontWeight: '600' }}>Individual Student Attention</p>
          </div>

        </div>
      </div>

      <Features />
    </div>
  );
}
